<?php $user=App\middleware\Auth::user();$role=$user['role']??'guest';$current=parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH);$cartCount=$role==='retailer'?(int)(App\Models\DB::one('SELECT COALESCE(SUM(ci.quantity),0) n FROM cart_items ci JOIN carts c ON c.id=ci.cart_id WHERE c.retailer_id=?',[$user['id']])['n']??0):0;$unread=$user?(int)App\Models\DB::one('SELECT COUNT(*) n FROM messages m JOIN conversation_participants cp ON cp.conversation_id=m.conversation_id WHERE cp.user_id=? AND m.sender_id<>? AND (cp.last_read_at IS NULL OR m.created_at>cp.last_read_at)',[$user['id'],$user['id']])['n']:0;
$nav=$role==='admin'?['/admin'=>'Overview','/admin/users'=>'Businesses','/admin/catalog'=>'Catalog','/orders'=>'Orders','/admin/payments'=>'Payments','/admin/imports'=>'Comparisons','/admin/settings'=>'Settings','/admin/audit'=>'Activity log']:($role==='wholesaler'?['/dashboard'=>'Overview','/listings'=>'My listings','/orders'=>'Orders','/messages'=>'Messages','/profile'=>'Business settings']:['/dashboard'=>'Overview','/catalog'=>'Marketplace','/orders'=>'My orders','/expenses'=>'Expenses','/messages'=>'Messages']);
?>
